('starter-ratio-1','ratio','Constitutional','principle','[{"id":"principle","text":"Parliament cannot use its amending power under Article 368 to damage or destroy the ''basic structure'' of the Constitution."},{"id":"alternative","text":"Parliament’s power under Article 368 is unlimited, including the power to destroy the Constitution’s basic structure."}]'),
('starter-ratio-2','ratio','Constitutional','principle','[{"id":"principle","text":"Any procedure that deprives a person of life or personal liberty under Article 21 must be fair, just, and reasonable — not arbitrary or oppressive."},{"id":"alternative","text":"Any procedure enacted by law satisfies Article 21, even if it is arbitrary or oppressive."}]'),
('starter-ratio-3','ratio','Criminal','principle','[{"id":"principle","text":"The death penalty should be imposed only in the ''rarest of rare'' cases, where the alternative option of life imprisonment is unquestionably foreclosed."},{"id":"alternative","text":"The death penalty is the default sentence for murder, without considering life imprisonment."}]'),
('starter-ratio-4','ratio','Tort/Environmental','principle','[{"id":"principle","text":"An enterprise engaged in a hazardous or inherently dangerous activity owes an absolute and non-delegable duty to the community, with no exceptions for ''Act of God'' or third-party fault."},{"id":"alternative","text":"A hazardous enterprise has no responsibility for harm unless the injured person proves the enterprise’s negligence."}]'),
('starter-ratio-5','ratio','Constitutional/Labour','principle','[{"id":"principle","text":"In the absence of domestic legislation, international conventions (like CEDAW) can be read into Articles 14, 19, and 21 to fill the gap, and the Vishaka Guidelines are binding until Parliament legislates."},{"id":"alternative","text":"A court cannot protect constitutional rights against workplace sexual harassment until a specific domestic statute is enacted."}]'),
('starter-ratio-6','ratio','Constitutional/IT Law','principle','[{"id":"principle","text":"Section 66A is unconstitutional as it is vague, overbroad, and has a chilling effect on the fundamental right to freedom of speech and expression under Article 19(1)(a)."},{"id":"alternative","text":"Section 66A remains valid whenever an online message causes annoyance, even if it falls outside Article 19(2)."}]'),
